// Sub Tightener: Suno Studio audio effect for the BASS stem (applied to rendered audio, not a lyric tag).
// Signal chain, in order:
//   1. Input trim: convert 'input gain' dB to linear and scale each channel.
//   2. Sub-rumble removal: g.biquad highpass at 'hp freq' to clear inaudible sub energy.
//   3. Low band isolate: g.biquad lowpass near 120Hz splits the low band from the rest (rest = trimmed - low).
//   4. Tame boom: g.asymmetricOnePole tracks g.abs(low) as an envelope (fixed attack/release coefs derived
//      from time constants and config.sampleRate via coef = clamp(1 - 1/(seconds*sr), 0, 0.9999) as in de-esser).
//      The envelope, scaled by 'tighten' percent, attenuates the low band to control boom, then recombine.
//   5. Warmth: g.biquad lowshelf near 90Hz driven by 'warmth' dB for controlled weight.
//   6. Drive: scale by 'drive' (dB via g.dbToLin) then g.tanh for solidity.
//   7. Dry/wet: g.lerp between trimmed dry and processed by 'dry/wet mix'.
//   8. Output gain, bypass select via g.lerp, then g.tanh safety before g.output.
// Bypass: g.lerp(bypass, out, trimmed) ASSUMES the 'bypass' enum resolves to 0 ('off') / 1 ('on'), so
// 'off' passes the PROCESSED signal and 'on' passes the DRY signal (see AUTHORING.md).
// ASSUMPTION: the shelf g.biquad stage passes a 'gainDb' field not confirmed from the one example (see AUTHORING.md).
function build(g, config) {
  var inL = g.input('audioInL');
  var inR = g.input('audioInR');

  var inGainDb = g.input('input gain');
  var hpFreq = g.input('hp freq');
  var tightenPct = g.input('tighten');
  var warmthDb = g.input('warmth');
  var driveDb = g.input('drive');
  var mixPct = g.input('dry/wet mix');
  var outGainDb = g.input('output gain');
  var bypass = g.input('bypass');

  var inGain = g.dbToLin(inGainDb);
  var outGain = g.dbToLin(outGainDb);
  var driveLin = g.dbToLin(driveDb);
  var mix = g.clamp(g.div(mixPct, g.constant(100)), g.zero(), g.constant(1));
  var tighten = g.clamp(g.div(tightenPct, g.constant(100)), g.zero(), g.constant(1));
  var sr = g.constant(config.sampleRate);

  // one-pole coef approximation: coef = clamp(1 - 1/(seconds*sr), 0, 0.9999) (fixed 5ms attack, 80ms release).
  var attackSamples = g.max(g.mul(g.constant(0.005), sr), g.constant(1));
  var releaseSamples = g.max(g.mul(g.constant(0.08), sr), g.constant(1));
  var attackCoef = g.clamp(g.sub(g.constant(1), g.div(g.constant(1), attackSamples)), g.zero(), g.constant(0.9999));
  var releaseCoef = g.clamp(g.sub(g.constant(1), g.div(g.constant(1), releaseSamples)), g.zero(), g.constant(0.9999));

  function chain(x) {
    var trimmed = g.mul(x, inGain);
    var hp = g.biquad({ input: trimmed, cutoff: hpFreq, resonance: g.constant(0.707), mode: 'highpass' });
    var low = g.biquad({ input: hp, cutoff: g.constant(120), resonance: g.constant(0.707), mode: 'lowpass' });
    var rest = g.sub(hp, low);
    var env = g.asymmetricOnePole({ target: g.abs(low), attackCoef: attackCoef, releaseCoef: releaseCoef });
    var duckAmt = g.mul(env, tighten);
    var tamedLow = g.sub(low, g.mul(low, g.clamp(duckAmt, g.zero(), g.constant(1))));
    var recombined = g.add(rest, tamedLow);
    var warm = g.biquad({ input: recombined, cutoff: g.constant(90), resonance: g.constant(0.707), mode: 'lowshelf', gainDb: warmthDb });
    var driven = g.tanh(g.mul(warm, driveLin));
    var wet = g.lerp(mix, trimmed, driven);
    var out = g.mul(wet, outGain);
    var active = g.lerp(bypass, out, trimmed);
    return g.tanh(active);
  }

  g.output('audioOutL', chain(inL));
  g.output('audioOutR', chain(inR));
}
